#include <iostream>
#include <string>
using namespace std;

char st[100005];
int top = -1;

int main() {
    string s;
    getline(cin, s);

    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st[++top] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top < 0) { cout << "NO\n"; return 0; }
            char t = st[top];
            bool ok = (c == ')' && t == '(') || (c == ']' && t == '[') || (c == '}' && t == '{');
            if (!ok) { cout << "NO\n"; return 0; }
            top--;
        }
    }
    cout << (top < 0 ? "YES\n" : "NO\n");
    return 0;
}
